@startuml
class Employee {
  +identifyingNumber : int
  +name : string
  +address : string
}

class PartAccessory {
  +category : string
  +serialNumber : string
  +price : double
}

class Car {
  +licensePlate : string
  +make : string
  +model : string
  +color : string
}

class Owner {
  +name : string
  +identifyingNumber : string
  +address : string
  +phone : string
}

class AssemblyService {
  +kms : int
  +workHours : float
  +admissionDate : date
  +finishDate : date
}

class CarModelFit {
}

Owner "1" -- "*" Car : owns
Employee "1" -- "*" AssemblyService : responsible for
Car "1" -- "*" AssemblyService : executed in
AssemblyService "*" -- "*" PartAccessory : fitted with
PartAccessory "*" -- "*" CarModelFit : fits
Car "1" -- "*" CarModelFit : is a model for
@enduml

